            },
            "status": {
                "type": "string",
                "description": "Task completion status",
                "source": "=result.Action",
                "var": "status",
                "enum": ["Approve", "Reject"],
                "default": "Approve"
            }
        }
    },
    {
        "id": "logApproval",
        "type": "core.action.script",
        "typeVersion": "1.0",
        "display": {"label": "Log Approval"},
        "inputs": {
            "script": 'return { message: "Approval recorded." };'
        },
        "outputs": {
            "output": {
                "type": "object",
                "description": "The return value of the script",
                "source": "=result.response",
                "var": "output"
            },
            "error": {
                "type": "object",
                "description": "Error information if the node fails",
                "source": "=Error",
                "var": "error"
            }
        }
    },
    {
        "id": "end1",
        "type": "core.control.end",
        "typeVersion": "1.0",
        "display": {"label": "End"},
        "inputs": {}
    }
]

# --- EDGES ---
flow["edges"] = [
    {"id": "edge-start-hitl",   "sourceNodeId": "start",        "sourcePort": "output",    "targetNodeId": "hitlApproval", "targetPort": "input"},
